template <class T, class L> static T* upart(T* first, T* last, T pivot, L lt) {
    for (;;) {
        while (lt(*first, pivot)) ++first;
        --last;
        while (lt(pivot, *last)) --last;
        if (!(first < last)) return first;
        T t = *first; *first = *last; *last = t; ++first;
